use crate::runtime::{MethodRef, NativeError, Value};
#[derive(Debug, PartialEq)] pub enum UrlError { Relative, UnknownProtocol }
fn scheme(uri:&str)->Option<&str>{ let (s,rest)=uri.split_once(':')?; if s.is_empty() || !s.bytes().enumerate().all(|(i,b)| b.is_ascii_alphabetic() || (i>0 && (b.is_ascii_digit()||matches!(b,b'+'|b'-'|b'.')))) || rest.contains('/') && rest.find('/').is_some_and(|i| i < s.len()) {None} else {Some(s)} }
pub fn to_url_text(uri:&str)->Result<String,UrlError>{ let s=scheme(uri).ok_or(UrlError::Relative)?; if !matches!(s,"http"|"https"|"file"|"jar"|"ftp"|"mailto"|"jrt"|"jmod"){return Err(UrlError::UnknownProtocol)}; if uri.starts_with(&format!("{s}:///")){return Ok(format!("{s}:/{}",&uri[s.len()+4..]))} Ok(uri.to_owned()) }
pub fn instance_call(r:&MethodRef,receiver:&Value)->Option<Result<Value,NativeError>>{if r.owner!="java/net/URI"||r.name!="toURL" {return None} let text=crate::runtime::host_jdk_value::uri_text(receiver)?;Some(match to_url_text(text){Ok(t)=>Ok(Value::Host(crate::runtime::host_ref::HostRef::new(crate::runtime::host_ref::HostKind::Url,t))),Err(UrlError::Relative)=>Err(NativeError::UncaughtException{class:"java/lang/IllegalArgumentException".into(),message:Some("URI is not absolute".into()),frame:None}),Err(UrlError::UnknownProtocol)=>Err(NativeError::UncaughtException{class:"java/net/MalformedURLException".into(),message:Some(format!("unknown protocol: {}",text.split(':').next().unwrap_or(""))),frame:None})})}
